  'portfolio_kbdny_content' => '    <h3>نظرة عامة على المشروع</h3>    <p>منصة \\\\\\"قبضني\\\\\\" (Kbdny) هي نظام مؤسسي متكامل للدروبشيبينغ والتسويق بالعمولة، يهدف إلى سد الفجوة بين موردي المنتجات (البائعين) والمسوقين بالعمولة. تم بناء النظام باستخدام إطار عمل Laravel ليكون قادراً على التعامل مع حجم عمليات ضخم، حيث يوفر لوحة تحكم تشغيلية متكاملة لإدارة لوجستيات الدروبشيبينغ، حساب العمولات الديناميكية، وإدارة الطلبات المعقدة.</p>        <h3>أهم الميزات</h3>    <ul>        <li><strong>هيكلة الصلاحيات المتعددة:</strong> نظام أذونات دقيق يفصل العمليات بين مديري النظام، الموردين (Vendors)، المسوقين (Affiliates)، مساعدي المسوقين (Moderators)، والعملاء النهائيين.</li>        <li><strong>إدارة متقدمة للمخزون والمنتجات (SKU):</strong> توليد تلقائي لرموز SKU، تتبع المتغيرات المتعددة للمنتج، مزامنة تلقائية لمستويات المخزون عبر الموردين، وأدوات متطورة لتسعير المنتجات ومسارات الموافقة عليها.</li>        <li><strong>عمليات التسويق والعمولات:</strong> بوابات مخصصة للمسوقين تمكنهم من إنشاء مفاتيح API، تتبع العمولات لحظياً، إدارة سلات التسوق الخاصة بهم، ومتابعة عمليات الدفع وسحب الأرباح.</li>        <li><strong>اللوجستيات وتلبية الطلبات:</strong> أدوات شاملة لتتبع حالات الطلبات بما في ذلك التسليم الجزئي، الاسترجاع، والاستبدال. يتكامل النظام بسلاسة مع شركات الشحن الخارجية باستخدام تصدير مجمع لملفات Excel (مثل R2S، Sheet2) لتسريع وتيرة العمليات.</li>        <li><strong>التتبع المالي:</strong> محفظة مدمجة ونظام طلبات دفع يعالج سحب الأرباح الديناميكي، تعديل الأرصدة، واقتطاع رسوم المنصة بدقة.</li>    </ul>    <h3>أبرز التقنيات المستخدمة</h3>    <p>تم تطوير المنصة بأحدث ممارسات لغة PHP على إطار عمل Laravel. يعتمد التطبيق على نظام طوابير (Queues) متطور لمعالجة الطلبات الجماعية، وعلاقات قواعد بيانات معقدة لتوزيع العمولات على مستويات متعددة، بالإضافة إلى واجهات برمجة تطبيقات (APIs) آمنة للتكامل مع أنظمة المسوقين الخارجية. كما تضمن واجهة المستخدم سرعة التشغيل من خلال إمكانيات التعديل الجماعي والتتبع اللحظي لحالة النظام.</p>  ',
  'portfolio_kbdny_desc' => 'نظام متكامل واحترافي للتجارة الإلكترونية والدروبشيبينغ. يتميز بإدارة متقدمة للمخزون والمنتجات، نظام صلاحيات متعدد (بائعين، مسوقين، مشرفين)، معالجة الطلبات الجماعية عبر ملفات Excel، تتبع العمولات اللحظي، وإدارة لوجستية معقدة تشمل المرتجعات، التسليم الجزئي، والمدفوعات الإلكترونية.',
  'portfolio_kbdny_title' => 'منصة قبضني لدروبشيبينغ والتسويق بالعمولة',
  'portfolio_khamsat_notifier_desc' => 'Browser extension for real-time طلب إشعارات on Khamsat marketplace.',
  'portfolio_khamsat_notifier_title' => 'Khamsat Notifier',
  'portfolio_live_url' => 'رابط الموقع (الرابط المباشر)',
  'portfolio_map_extractor_desc' => 'Business العملاء المحتملين extraction أداة with filtering and تصدير capabilities.',
  'portfolio_map_extractor_title' => 'Map Extractor',
  'portfolio_mini_fatora_content' => '    <h3>نظرة عامة على المشروع</h3>    <p>ميني فاتورة هي منصة سحابية (SaaS) متكاملة لإصدار الفواتير والفوترة عبر الإنترنت مصممة خصيصاً للمستقلين والشركات الصغيرة والمهنيين المستقلين. تعمل المنصة على تبسيط عملية الفوترة، مما يساعد المستخدمين على تحصيل أموالهم بشكل أسرع وإدارة عملياتهم المالية بكل سهولة.</p>        <h3>الميزات الرئيسية</h3>    <ul>        <li><strong>الفوترة الآلية:</strong> إنشاء وإرسال فواتير احترافية في ثوانٍ، مع دعم لعملات متعددة وقواعد الضرائب.</li>        <li><strong>إدارة العملاء:</strong> الاحتفاظ بدليل مركزي لجميع العملاء، وتتبع سجلات الدفع، وإدارة الأرصدة المستحقة.</li>        <li><strong>تتبع النفقات:</strong> تسجيل نفقات العمل بسهولة وتصنيفها لتحسين إعداد التقارير المالية والضرائب.</li>        <li><strong>المدفوعات عبر الإنترنت:</strong> التكامل مع بوابات الدفع الشهيرة للسماح للعملاء بالدفع مباشرة من رابط الفاتورة.</li>        <li><strong>التقارير المالية:</strong> الوصول إلى لوحات معلومات في الوقت الفعلي وإنشاء تقارير مفصلة عن الدخل والنفقات والصحة العامة للعمل.</li>    </ul>    <h3>أبرز النقاط الفنية</h3>    <p>تم بناء المنصة مع التركيز على السرعة والأمان وتجربة المستخدم. تستخدم المنصة أحدث تقنيات الويب لضمان التجاوب عبر الأجهزة المختلفة، مع تشفير آمن للبيانات السجلات المالية، وبنية قابلة للتوسع لدعم احتياجات العمل المتنامية.</p>  ',
